begin;
select no_plan();
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001','create','99000000-0000-4000-8000-000000000010',null,'{"name":"Freezer curry","portions":2,"frozenOn":"2026-10-06"}')$$,'Owner creates stock through atomic boundary');
select throws_ok($$insert into cooksmith.freezer_meals(household_id,name,portions,frozen_on) values('20000000-0000-4000-8000-000000000001','Forged',100,'2026-10-06')$$,'42501',null,'Direct stock creation denied');
select throws_ok($$update cooksmith.freezer_meals set portions=100$$,'42501',null,'Direct stock edits denied');
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001','create','99000000-0000-4000-8000-000000000010',null,'{"name":"Freezer curry","portions":2,"frozenOn":"2026-10-06"}')$$,'Exact retry returns receipt');
select is((select count(*) from cooksmith.freezer_meals),1::bigint,'Retry did not duplicate stock');
select throws_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001','create','99000000-0000-4000-8000-000000000010',null,'{"name":"Changed","portions":99,"frozenOn":"2026-10-06"}')$$,'23514',null,'Operation key cannot be reused for different request');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000002','reserve','99000000-0000-4000-8000-000000000010','99000000-0000-4000-8000-000000000020','{"portions":2,"mealDate":"2026-10-07"}')$$,'Member reserves portions and creates a plan atomically');
select is((select portions from cooksmith.freezer_meals),2,'Reservation does not consume stock');
select throws_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'reserve','99000000-0000-4000-8000-000000000010',gen_random_uuid(),'{"portions":1,"mealDate":"2026-10-08"}')$$,'23514',null,'Conflicting reservation cannot oversubscribe');
select throws_ok($$update cooksmith.planned_meals set freezer_meal_id=null where id='99000000-0000-4000-8000-000000000020'$$,'42501',null,'Direct mutation cannot erase freezer provenance');
select throws_ok($$insert into cooksmith.planned_meals(household_id,title,meal_date,meal_type,freezer_meal_id) values('20000000-0000-4000-8000-000000000001','Forged stock','2026-10-08','dinner','99000000-0000-4000-8000-000000000010')$$,'42501',null,'Direct planner insert cannot forge a reservation');
select throws_ok($$select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000020','[{"name":"carrot","quantity":2,"unit":null,"category":"produce"}]')$$,'23514',null,'Freezer provenance rejects shopping contributions server-side');
select is((select count(*) from cooksmith.shopping_item_contributions where planned_meal_id='99000000-0000-4000-8000-000000000020'),0::bigint,'Rejected shopping request leaves no partial contributions');
select lives_ok($$update cooksmith.planned_meals set meal_date='2026-10-09' where id='99000000-0000-4000-8000-000000000020'$$,'Moving plan retains reservation');
select is((select portions from cooksmith.freezer_meal_reservations),2,'Move preserved portions');
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000003','consume','99000000-0000-4000-8000-000000000010','99000000-0000-4000-8000-000000000020','{}')$$,'Explicit consume succeeds');
select is((select portions from cooksmith.freezer_meals),0,'Consume decrements physical stock exactly');
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000003','consume','99000000-0000-4000-8000-000000000010','99000000-0000-4000-8000-000000000020','{}')$$,'Consume network retry is idempotent');
select is((select portions from cooksmith.freezer_meals),0,'Retry cannot decrement again');
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'undo','99000000-0000-4000-8000-000000000010','99000000-0000-4000-8000-000000000020','{}')$$,'Undo returns physical stock and reservation');
select is((select portions from cooksmith.freezer_meals),2,'Undo restores stock');
select is((select state from cooksmith.freezer_meal_reservations),'reserved','Undo re-establishes reservation');
select throws_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'edit','99000000-0000-4000-8000-000000000010',null,'{"name":"Stale","portions":9,"frozenOn":"2026-10-06","revision":0}')$$,'PT409',null,'Stale edit cannot overwrite consumed/reserved changes');
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'archive','99000000-0000-4000-8000-000000000010',null,'{}')$$,'Archive keeps existing reservation');
select is((select count(*) from cooksmith.freezer_meal_reservations),1::bigint,'Archive preserved reservation');
select throws_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'reserve','99000000-0000-4000-8000-000000000010',gen_random_uuid(),'{"portions":1,"mealDate":"2026-10-08"}')$$,'23514',null,'Archived stock cannot be newly reserved');
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'restore','99000000-0000-4000-8000-000000000010',null,'{}')$$,'Restore stock');
select lives_ok($$delete from cooksmith.planned_meals where id='99000000-0000-4000-8000-000000000020'$$,'Deleting reserved plan releases reservation');
select is((select count(*) from cooksmith.freezer_meal_reservations),0::bigint,'No reservation remains');
select is((select portions from cooksmith.freezer_meals),2,'Release does not change physical stock');
select is((select count(*) from cooksmith.freezer_meal_events where action='release'),1::bigint,'Release leaves event evidence');
select lives_ok($$insert into cooksmith.household_recipes(id,household_id,name) values('99000000-0000-4000-8000-000000000030','20000000-0000-4000-8000-000000000001','Optional freezer recipe')$$,'Synthetic optional recipe created');
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'create','99000000-0000-4000-8000-000000000011',null,'{"name":"Linked soup","portions":1,"frozenOn":"2026-10-06","householdRecipeId":"99000000-0000-4000-8000-000000000030"}')$$,'Optional recipe link does not change stock source');
select lives_ok($$update cooksmith.household_recipes set archived_at=now() where id='99000000-0000-4000-8000-000000000030'$$,'Recipe can be archived independently');
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'edit','99000000-0000-4000-8000-000000000011',null,'{"name":"Linked soup","portions":1,"frozenOn":"2026-10-06","householdRecipeId":"99000000-0000-4000-8000-000000000030","notes":"Use this week","revision":0}')$$,'Editing stock preserves an existing unavailable recipe link');
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'reserve','99000000-0000-4000-8000-000000000011','99000000-0000-4000-8000-000000000021','{"portions":1,"mealDate":"2026-10-08"}')$$,'Archived optional recipe does not prevent using prepared stock');
select throws_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'edit','99000000-0000-4000-8000-000000000011',null,jsonb_build_object('name','Soup','portions',0,'frozenOn','2026-10-06','revision',(select revision from cooksmith.freezer_meals where id='99000000-0000-4000-8000-000000000011')))$$,'23514',null,'Current edit cannot reduce physical stock below reserved portions');
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'consume','99000000-0000-4000-8000-000000000011','99000000-0000-4000-8000-000000000021','{}')$$,'Consume stock with archived recipe');
select lives_ok($$delete from cooksmith.planned_meals where id='99000000-0000-4000-8000-000000000021'$$,'Consumed plan can be removed explicitly');
select is((select portions from cooksmith.freezer_meals where id='99000000-0000-4000-8000-000000000011'),0,'Deleting consumed plan does not silently return eaten food');
-- Replacing an existing dinner must reconcile its generated shopping atomically.
insert into cooksmith.planned_meals(id,household_id,meal_date,meal_type,title) values('99000000-0000-4000-8000-000000000022','20000000-0000-4000-8000-000000000001','2026-10-09','dinner','Cook from scratch');
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000022','[{"name":"freezer test carrot","quantity":2,"unit":null,"category":"produce"},{"name":"freezer test salt","quantity":20,"unit":"g","category":"pantry"}]');
select cooksmith.update_shopping_purchase('20000000-0000-4000-8000-000000000001',(select jsonb_agg(jsonb_build_object('id',id,'name',display_name,'quantity',30,'unit',unit,'category',category)) from cooksmith.shopping_list_items where display_name='freezer test salt'));
select lives_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'reserve','99000000-0000-4000-8000-000000000010','99000000-0000-4000-8000-000000000022','{"portions":1,"mealDate":"2026-10-09"}')$$,'Existing dinner can be replaced atomically by freezer stock');
select is((select count(*) from cooksmith.shopping_item_contributions where planned_meal_id='99000000-0000-4000-8000-000000000022'),0::bigint,'Replacement removes all old generated contributions');
select is((select count(*) from cooksmith.shopping_list_items where display_name='freezer test carrot'),0::bigint,'Generated-only purchase disappears');
select is((select quantity from cooksmith.shopping_list_items where display_name='freezer test salt' and manual),30::numeric,'Explicit household adjustment remains a manual purchase');
select is((select freezer_meal_id from cooksmith.planned_meals where id='99000000-0000-4000-8000-000000000022'),'99000000-0000-4000-8000-000000000010'::uuid,'Replacement preserves plan identity with freezer provenance');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select is((select count(*) from cooksmith.freezer_meals),0::bigint,'Unrelated household sees no stock');
select throws_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'restore','99000000-0000-4000-8000-000000000010',null,'{}')$$,'42501',null,'Forged household command denied');
select throws_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000002',gen_random_uuid(),'restore','99000000-0000-4000-8000-000000000010',null,'{}')$$,'42501',null,'Own household cannot mutate foreign stock identifier');
reset role;
update cooksmith.household_members set status='inactive',inactive_at=now() where user_id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select throws_ok($$select cooksmith.freezer_command('20000000-0000-4000-8000-000000000001',gen_random_uuid(),'restore','99000000-0000-4000-8000-000000000010',null,'{}')$$,'42501',null,'Inactive member cannot command stock');
reset role;
select ok(not has_function_privilege('anon','cooksmith.freezer_command(uuid,uuid,text,uuid,uuid,jsonb)','execute'),'Anonymous RPC access denied');
select * from finish();
rollback;
